  ('pt-BR', 'jev.validate.hint', $json$"Depois de um pedido de desenvolvimento, roda os testes, o lint, o typecheck e o build do projeto e mostra o que passou. Opcional; a organização pode exigir."$json$::jsonb),
  ('es', 'jev.validate.hint', $json$"Tras una petición de desarrollo, ejecuta las pruebas, el lint, el typecheck y el build del proyecto y muestra lo que pasó. Opcional; la organización puede exigirlo."$json$::jsonb),
  ('zh-CN', 'jev.validate.hint', $json$"开发请求之后，运行项目的测试、lint、typecheck 和构建，并显示哪些通过。可选；组织可以强制要求。"$json$::jsonb),
